<script setup>
import AuthenticatedLayout from '@/Layouts/AuthenticatedLayout.vue'; import InputError from '@/Components/InputError.vue'; import {Head,Link,router,useForm} from '@inertiajs/vue3';
const props=defineProps({asset:Object}); const remove=()=>{if(confirm(`Remove ${props.asset.name}?`)) router.delete(route('assets.destroy',props.asset.id));};
const attestation=useForm({result:props.asset.is_internet_facing?'exposed':'not_exposed',note:'',recheck_at:''});
const record=()=>attestation.post(route('assets.exposure.manual',props.asset.id),{preserveScroll:true,onSuccess:()=>attestation.reset('note')});
const details=[['Vendor',props.asset.vendor],['Model',props.asset.model],['Firmware',props.asset.firmware_version],['Internal IP',props.asset.internal_ip],['External IP',props.asset.external_ip],['Monitoring source',props.asset.data_source_type?.replace('_',' ')],['Criticality',props.asset.criticality]];
</script>
<template><Head :title="asset.name"/><AuthenticatedLayout><template #header><div class="flex items-center justify-between"><div><p class="text-sm font-medium uppercase tracking-wide text-teal-700">{{asset.asset_type}}</p><h1 class="text-2xl font-semibold">{{asset.name}}</h1></div><div class="flex gap-2"><Link :href="route('assets.edit',asset.id)" class="rounded-lg border px-4 py-2 text-sm font-medium">Edit</Link><button @click="remove" class="rounded-lg border border-red-200 px-4 py-2 text-sm text-red-700">Remove</button></div></div></template><div class="mx-auto grid max-w-6xl gap-6 px-4 py-8 lg:grid-cols-[3fr_2fr]"><div class="space-y-6"><section class="rounded-xl border bg-white p-6 shadow-sm"><h2 class="text-lg font-semibold">Device details</h2><dl class="mt-5 grid gap-5 sm:grid-cols-2"><div v-for="([label,value]) in details" :key="label"><dt class="text-xs font-semibold uppercase text-slate-500">{{label}}</dt><dd class="mt-1 capitalize">{{value||'Not recorded'}}</dd></div></dl><div class="mt-6 border-t pt-5"><h3 class="text-sm font-semibold">Notes and compensating controls</h3><p class="mt-2 whitespace-pre-wrap text-sm text-slate-600">{{asset.notes||'None recorded.'}}</p></div></section><section class="rounded-xl border bg-white p-6 shadow-sm"><h2 class="text-lg font-semibold">Exposure history</h2><div class="mt-4 divide-y"><div v-for="scan in asset.exposure_scans" :key="scan.id" class="py-3"><div class="flex justify-between gap-3"><span class="font-medium" :class="scan.result==='exposed'?'text-red-700':'text-slate-800'">{{scan.result==='exposed'?'Reachable from the internet':scan.result.replace('_',' ')}}</span><time class="text-xs text-slate-500">{{new Date(scan.scanned_at).toLocaleString()}}</time></div><p class="mt-1 text-xs capitalize text-slate-500">{{scan.method}} check<span v-if="scan.note"> · {{scan.note}}</span></p></div><p v-if="!asset.exposure_scans.length" class="py-8 text-center text-sm text-slate-500">No exposure checks yet.</p></div></section></div><aside class="space-y-5"><div class="rounded-xl border p-5 shadow-sm" :class="asset.is_internet_facing?'border-red-300 bg-red-50':'bg-white'"><p class="text-xs font-semibold uppercase text-slate-500">Current exposure</p><p class="mt-2 text-lg font-semibold" :class="asset.is_internet_facing?'text-red-700':'text-emerald-700'">{{asset.is_internet_facing?'This device can currently be reached from the internet':'Not known to be internet-reachable'}}</p></div><form @submit.prevent="record" class="rounded-xl border bg-white p-5 shadow-sm"><h2 class="font-semibold">Record a manual check</h2><p class="mt-1 text-xs text-slate-500">Use this when an operator has verified the device or firewall state.</p><label class="mt-4 block text-sm font-medium">Result</label><select v-model="attestation.result" class="mt-1 w-full rounded-lg border-slate-300"><option value="not_exposed">Not reachable from internet</option><option value="exposed">Reachable from internet</option><option value="unknown">Could not verify</option></select><label class="mt-4 block text-sm font-medium">Verification note *</label><textarea v-model="attestation.note" required rows="3" class="mt-1 w-full rounded-lg border-slate-300" placeholder="What was checked and by whom?"></textarea><InputError :message="attestation.errors.note"/><label class="mt-4 block text-sm font-medium">Check again on</label><input v-model="attestation.recheck_at" type="date" class="mt-1 w-full rounded-lg border-slate-300"/><InputError :message="attestation.errors.recheck_at"/><button class="mt-4 w-full rounded-lg bg-teal-700 px-4 py-2 text-sm font-semibold text-white">Save exposure check</button></form></aside></div></AuthenticatedLayout></template>
